119		stats := TimeStats{Buckets: make([]TimeBucket, count)}
120		for i := range stats.Buckets {
121			stats.Buckets[i].Start = bucketBoundary(query.Start, query.StepSeconds, int64(i))
122			// A saturated boundary (MaxInt64) and the overshooting final step
123			// are both cut back to the requested window end.
124			end := bucketBoundary(query.Start, query.StepSeconds, int64(i)+1)
125			if end > query.End {
126				end = query.End
127			}
128			stats.Buckets[i].End = end
129		}
130	
131		index.mu.Lock()
132		defer index.mu.Unlock()
133	
134		if to == 0 || to > index.Tip {
135			to = index.Tip
136		}
137		stats.FromHeight = from
138		stats.ToHeight = to
139		if from > to {
140			// Empty index or a start above the tip: zeroed buckets are still
141			// returned for the whole requested window.
142			return stats, nil
143		}
144	
145		if statsQueryHookLocked != nil {
146			statsQueryHookLocked(to)
147		}
148	
149		distinct := make([]map[string]struct{}, count)
150		windowDistinct := make(map[string]struct{})
151		for height := from; height <= to; height++ {
152			block := index.Blocks[height]
153			if block.Time == nil {
154				stats.MissingTimeBlocks++
155				continue
156			}
157			t := *block.Time
