168				stats.Totals.TxCount++
169				if distinct[bucket] == nil {
170					distinct[bucket] = make(map[string]struct{})
171				}
172				distinct[bucket][tx] = struct{}{}
173				windowDistinct[tx] = struct{}{}
174				matched = true
175			}
176			if matched {
177				stats.Buckets[bucket].Blocks++
178				stats.Totals.Blocks++
179			}
180		}
181		for i := range distinct {
182			stats.Buckets[i].DistinctTxIDs = int64(len(distinct[i]))
183		}
184		stats.Totals.DistinctTxIDs = int64(len(windowDistinct))
185		return stats, nil
186	}
