1	package indexroom
2	
3	import (
4		"fmt"
5		"reflect"
6		"testing"
7	)
8	
9	// referenceScan independently computes the full filtered occurrence list and
10	// matched-block count for [from, to], the same way the old collectLocked did,
11	// so the page-sized scan can be compared against an oracle that keeps every
12	// record.
13	func referenceScan(index *Index, from, to int64, txIDs []string) ([]TxHit, int64) {
14		filter := map[string]struct{}{}
15		for _, id := range txIDs {
16			filter[id] = struct{}{}
17		}
18		var all []TxHit
19		var blocks int64
20		for height := from; height <= to; height++ {
21			block := index.Blocks[height]
22			matched := false
23			for position, tx := range block.Txs {
24				if len(txIDs) > 0 {
25					if _, ok := filter[tx]; !ok {
26						continue
27					}
28				}
29				all = append(all, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
30				matched = true
31			}
32			if matched {
33				blocks++
34			}
35		}
36		return all, blocks
37	}
38	
39	// TestScanPageLockedRetainsOnlyPageWindow is the memory contract behind the
40	// QueryTxs refactor: a scan may keep at most pageSize TxHit records no matter
41	// how many matches the pinned range holds, while totals still describe the
42	// whole range and every offset slices the same ordered occurrence list the
43	// old full-materialization scan would have produced.
44	func TestScanPageLockedRetainsOnlyPageWindow(t *testing.T) {
45		// 60 blocks, three txs each with repeated identifiers: 180 occurrences.
46		var blocks [][]string
47		for h := 0; h < 60; h++ {
48			blocks = append(blocks, []string{
49				fmt.Sprintf("t%d", h%5), // five ids cycling: selective filter
50				"keep",
51				"keep", // same id twice in one block: both occurrences survive
52			})
53		}
54		index := txChain(t, blocks...)
55	
56		const from, to = int64(1), int64(60)
57		all, matchedBlocks := referenceScan(index, from, to, nil)
58		if len(all) != 180 || matchedBlocks != 60 {
59			t.Fatalf("oracle setup: hits=%d blocks=%d, want 180/60", len(all), matchedBlocks)
60		}
61	
62		for _, pageSize := range []int{1, 2, 7, DefaultPageSize, MaxPageSize} {
63			var windowed []TxHit
64			for offset := int64(0); ; {
65				hits, total, gotBlocks := index.scanPageLocked(from, to, newTxFilter(nil), OrderAsc, offset, pageSize)
66				if total != int64(len(all)) {
67					t.Fatalf("pageSize=%d offset=%d: total=%d, want whole-range %d", pageSize, offset, total, len(all))
68				}
69				if gotBlocks != matchedBlocks {
70					t.Fatalf("pageSize=%d offset=%d: blocks=%d, want %d", pageSize, offset, gotBlocks, matchedBlocks)
71				}
72				if len(hits) > pageSize || cap(hits) > pageSize {
73					t.Fatalf("pageSize=%d offset=%d: scan retained len=%d cap=%d records, want at most %d",
74						pageSize, offset, len(hits), cap(hits), pageSize)
75				}
76				end := offset + int64(len(hits))
77				if end > int64(len(all)) || !reflect.DeepEqual(hits, all[offset:end]) {
78					t.Fatalf("pageSize=%d offset=%d: window does not match the full occurrence slice", pageSize, offset)
79				}
80				windowed = append(windowed, hits...)
81				if len(hits) < pageSize {
82					break // last, possibly partial page
83				}
84				offset = end
85			}
86			if !reflect.DeepEqual(windowed, all) {
87				t.Fatalf("pageSize=%d: walking windows lost or duplicated occurrences", pageSize)
88			}
89		}
90	
91		// A selective filter keeps the same contract on the filtered answer.
92		filtered, filteredBlocks := referenceScan(index, from, to, []string{"keep", "t1"})
93		hits, total, gotBlocks := index.scanPageLocked(from, to, newTxFilter([]string{"t1", "keep", "keep"}), OrderAsc, 3, 5)
94		if total != int64(len(filtered)) || gotBlocks != filteredBlocks {
95			t.Fatalf("filtered totals=%d/%d, want %d/%d", total, gotBlocks, len(filtered), filteredBlocks)
96		}
97		if !reflect.DeepEqual(hits, filtered[3:8]) {
98			t.Fatalf("filtered window=%v, want %v", hits, filtered[3:8])
99		}
100		if cap(hits) > 5 {
101			t.Fatalf("filtered scan retained cap=%d, want at most 5", cap(hits))
102		}
103	
104		// An offset beyond the matches keeps whole-range statistics but returns no
105		// records; the continuation caller turns this into ErrQueryChanged.
106		hits, total, gotBlocks = index.scanPageLocked(from, to, newTxFilter(nil), OrderAsc, int64(len(all))+10, 4)
107		if len(hits) != 0 || total != int64(len(all)) || gotBlocks != matchedBlocks {
108			t.Fatalf("beyond-end scan: hits=%d total=%d blocks=%d", len(hits), total, gotBlocks)
109		}
110	
111		// An empty range retains nothing and reports zero statistics.
112		hits, total, gotBlocks = index.scanPageLocked(100, 200, newTxFilter(nil), OrderAsc, 0, 10)
113		if len(hits) != 0 || cap(hits) > 10 || total != 0 || gotBlocks != 0 {
114			t.Fatalf("empty-range scan: hits=%v total=%d blocks=%d", hits, total, gotBlocks)
115		}
116	}
117	
118	// TestQueryTxsTemporaryRecordsDoNotScaleWithTotal is an end-to-end check that
119	// paging through a range with a tiny page size and a huge hit total works
120	// identically whether the answer is read in one page or many: the temporary
121	// footprint shrinks with the page size while all visible behavior is fixed.
122	func TestQueryTxsTemporaryRecordsDoNotScaleWithTotal(t *testing.T) {
123		var blocks [][]string
124		for h := 0; h < 40; h++ {
125			blocks = append(blocks, []string{"a", "b", "c", "d", "e"})
126		}
127		index := txChain(t, blocks...) // 200 matches
128	
129		full, err := index.QueryTxs(TxQuery{PageSize: MaxPageSize})
130		if err != nil {
131			t.Fatal(err)
132		}
133		if full.TotalMatches != 200 || full.MatchedBlocks != 40 {
134			t.Fatalf("unexpected totals: %+v", full)
135		}
136	
137		// Page size 1: 200 round trips, each retaining one hit while scanning.
138		pages := collectPages(t, index, TxQuery{PageSize: 1})
139		if len(pages) != 200 {
140			t.Fatalf("pages=%d, want 200", len(pages))
141		}
142		var all []TxHit
143		for i, page := range pages {
144			if page.TotalMatches != 200 || page.MatchedBlocks != 40 || page.ToHeight != 40 {
145				t.Fatalf("page %d statistics describe the page instead of the range: %+v", i, page)
146			}
147			if i < len(pages)-1 && len(page.Hits) != 1 {
148				t.Fatalf("page %d holds %d hits, want exactly one", i, len(page.Hits))
149			}
150			if i < len(pages)-1 && page.NextCursor == "" {
151				t.Fatalf("page %d unexpectedly the last", i)
152			}
153			all = append(all, page.Hits...)
154		}
155		if pages[len(pages)-1].NextCursor != "" {
156			t.Fatalf("last page must carry an empty cursor, got %q", pages[len(pages)-1].NextCursor)
157		}
158		if len(all) != 200 {
159			t.Fatalf("collected %d hits, want 200", len(all))
160		}
161		// The single large-page answer spans the same ordered occurrences.
162		if full.NextCursor != "" || len(full.Hits) != 200 {
163			t.Fatalf("unexpected large page: %d hits cursor=%q", len(full.Hits), full.NextCursor)
164		}
165		if !reflect.DeepEqual(all, full.Hits) {
166			t.Fatalf("page-size-1 walk differs from the full answer")
167		}
